//#region src/commands/thinking_spinner.ts
const FRAMES = [
	"⠋",
	"⠙",
	"⠹",
	"⠸",
	"⠼",
	"⠴",
	"⠦",
	"⠧",
	"⠇",
	"⠏"
];
const INTERVAL_MS = 80;
const CLEAR_LINE = "\r\x1B[2K";
function createThinkingSpinner(opts) {
	let message = "Thinking";
	let frame = 0;
	let timer;
	let stopped = false;
	const paint = () => {
		if (!opts.isTty || stopped) return;
		const glyph = FRAMES[frame % FRAMES.length];
		frame += 1;
		opts.out.write(`${CLEAR_LINE}${glyph} ${message}`);
	};
	return {
		start() {
			if (!opts.isTty || stopped) return;
			paint();
			timer = setInterval(paint, INTERVAL_MS);
			timer.unref();
		},
		setMessage(next) {
			message = next;
			paint();
		},
		stop() {
			if (stopped) return;
			stopped = true;
			if (timer) clearInterval(timer);
			if (opts.isTty) opts.out.write(CLEAR_LINE);
		}
	};
}
//#endregion
export { createThinkingSpinner };
